// 1. Load the API (a lazy chunk; once per page).
const api = await window.__loadHexAPI();

// 2. Keep your current build. toUrl() is exact even straight after an edit;
//    the address bar catches up about 400 ms later.
const original = new URL(location.href);
original.hash = await api.toUrl();

// 3. Read only: what is on the bench, and where a base can go.
const nodes = api.getState().nodes;
const sockets = api.openSockets({ family: 'piece', level: 0 });

// 4. Changes the build: replace it with one base, then add a second.
await api.load({ pieces: [{ q: 0, r: 0, level: 0, variant: 'full' }] });
const out = await api.apply({ op: 'place', at: { q: 1, r: 0, level: 0 }, variant: 'full' });
if (!out.ok) console.log(out.code, out.message, out.validAlternatives);

// 5. Read only: checks, parts list and a share link for this build.
const report = await api.validate();
const parts = api.bom().lines;
const share = new URL(location.href);
share.hash = await api.toUrl();

// 6. Put your own build back.
await api.load(original.href);

({ nodes: nodes.length, sockets: sockets.length, placed: out.ok, ok: report.ok, parts: parts.length, share: share.href });

const api = await window.__loadHexAPI();
const original = new URL(location.href);
original.hash = await api.toUrl();

// A real share link: two bases, a bin, two covers. Put any Hex Cluster
// link in its place, or just its '#v2s=…' part.
const SHARE_LINK = '#v2s=hY5BCoMwEEXv8tcjxG08SnER7RRDw5gmMRREz14StNJVN8Obz-PPrMjQLSFCr_CWR47QtxUvaEUIdTrO7CplE6yRBI3H4hw2qmL7X-wJUYwv3QW9ffLB45w5FIYiRaorfpdmD0L7GxT5W2ElckjHMhm5u6tQhMc0h2MPi5xkI5_pYOU6uk_8bgYrTX2237YP';
const opened = await api.load(SHARE_LINK);
if (!opened.ok) throw new Error(opened.message);
const { nodes } = api.getState();
const families = new Set(nodes.map((n) => n.family));
