const api = await window.__loadHexAPI();
const original = new URL(location.href);
original.hash = await api.toUrl();

// A real share link: one base, and a small pot on the bench beside it.
await api.load('#v2s=RYxBCsMgFETvMutfMFm6yj1KFmJ_qVS-Vo0UJHcvkZhuhjfwZhoq9ETI0A3RseUMfW_4QCtC6um5su9UTXJGCjSem_fYV0IWE4_JgdG9-WQbKqfBl-EkcypneRl5-L8vwraEsUmbDHL5eoop9CvEUG7fvMyzUqRILT1pwrrvPw');
const pot = api.getState().staging.props.find((p) => p.pot);
const mint = api.listProps().find((p) => p.plant && p.id.startsWith('mint'));

const filled = await api.apply({ op: 'fillPot', ref: pot.ref });
// a prop ref changes with the prop: plant in the ref the fill handed back
const planted = await api.apply({ op: 'plant', id: mint.id, in: filled.added[0] });
const now = api.getState().staging.props.find((p) => p.pot);

await api.load(original.href);
({ filled: filled.ok, planted: planted.ok, plant: now.pot.plant });

const api = await window.__loadHexAPI();
const original = new URL(location.href);
original.hash = await api.toUrl();

await api.load({ pieces: [{ q: 0, r: 0, level: 0, variant: 'full' }] });
const lid = api.openSockets({ family: 'cover', level: 0 }).find((s) => s.op.face === 'top');
const cover = (await api.apply(lid.op)).added[0];

// A tape measure on the cover, resting as the props panel would rest it.
const placed = await api.apply({ op: 'addProp', id: 'tape', on: cover });
// Move it along and turn it a quarter: the ref changes with it.
const moved = await api.apply({
    op: 'moveProp',
    ref: placed.added[0],
    on: cover,
    atMm: { x: 20, z: 0 },
    yawDeg: 90,
});
const props = api.getState().staging.props.length;

await api.load(original.href);
({ placed: placed.ok, moved: moved.ok, props });

const api = await window.__loadHexAPI();
const original = new URL(location.href);
original.hash = await api.toUrl();

await api.load({ pieces: [{ q: 0, r: 0, level: 0, variant: 'full' }] });
const socket = api.openSockets({ family: 'bin', level: 0 })[0];
const bin = (await api.apply(socket.op)).added.find((r) => r.startsWith('bin:'));

// Soil to the rim, then a plug plant seated in it.
const filled = await api.apply({ op: 'fillSoil', part: bin });
const mint = api.listProps().find((p) => p.plant && p.id.startsWith('mint'));
const planted = await api.apply({ op: 'plant', id: mint.id, in: bin });
const { soil, props } = api.getState().staging;

await api.load(original.href);
({ filled: filled.ok, soil: soil.length, planted: planted.ok, props: props.length });

