const api = await window.__loadHexAPI();
const original = new URL(location.href);
original.hash = await api.toUrl();

await api.load({ pieces: [{ q: 0, r: 0, level: 0, variant: 'full' }] });
// A second full base in the same cell: the rules say no, and say why.
const out = await api.apply({ op: 'place', at: { q: 0, r: 0, level: 0 }, variant: 'full' });
let retried = null;
if (!out.ok) {
    // branch on out.code, never on out.message
    const next = out.validAlternatives[0];
    if (next) retried = await api.apply(next.op);
}

await api.load(original.href);
({ ok: out.ok, code: out.ok ? null : out.code, retried: retried?.ok });

const api = await window.__loadHexAPI();
const original = new URL(location.href);
original.hash = await api.toUrl();

await api.load({ pieces: [{ q: 0, r: 0, level: 0, variant: 'full' }] });
const ops = [
    { op: 'place', at: { q: 1, r: 0, level: 0 }, variant: 'full' },
    { op: 'place', at: { q: 0, r: 0, level: 0 }, variant: 'full' }, // refused: occupied
];
// Atomic by default: one refusal undoes the whole batch.
const all = await api.applyAll(ops);
const after = api.getState().nodes.length;
// Try every op and report every refusal. Still atomic: one refusal means
// nothing is kept, but a batch with no refusal is kept whole (not a dry run).
const tried = await api.applyAll(ops, { stopOnRefusal: false });
const kept = api.getState().nodes.length;

await api.load(original.href);
({ rolledBack: all.rolledBack, after, refusals: tried.outcomes.filter((o) => !o.ok).length, kept });

const api = await window.__loadHexAPI();
const original = new URL(location.href);
original.hash = await api.toUrl();

await api.load({ pieces: [{ q: 0, r: 0, level: 0, variant: 'full' }] });
const bin = api.listParts().find((p) => p.name === 'Bin, full depth');
const sockets = api.openSockets({ family: bin.family, stem: bin.value, level: 0 });
const out = sockets.length ? await api.apply(sockets[0].op) : null;
// The parts list names it the same way, by its published part.
const line = api.bom().lines.find((l) => l.key === bin.part);

await api.load(original.href);
({ part: bin.part, placed: out?.ok, listed: line?.label === bin.name });

const api = await window.__loadHexAPI();
const original = new URL(location.href);
original.hash = await api.toUrl();

await api.load({ pieces: [{ q: 0, r: 0, level: 0, variant: 'full' }] });
const bin = api.openSockets({ family: 'bin', level: 0 })[0];
if (bin) await api.apply(bin.op);
// The link for your printer. Opening it downloads; this only reads it.
const { pack } = api.bom({ format: 'stl', bed: { x: 256, y: 256 } });

await api.load(original.href);
({ url: pack.url, why: pack.why, bed: pack.bed.x });
